-- B1iF pricing package, Manna Treads side: everything the price snapshot is built
-- from, as one result set (Call SQL runs one statement) - k says what a row is,
-- c01..c14 hold its values as text. manna_sap_pricing puts it together; no rule
-- is decided here. No database name: DB_NAME() tells ERPNext which company it is.
--   D  the company database            c01 name
--   L  price list 1                    c01 no, c02 name
--   P  item properties (all 64)        c01 no, c02 name
--   I  active items with any property ticked: c01 code, c02 name, c03 group no, c04 group name,
--        c05 sales item, c06 frozen, c07 inventory unit, c08 sales unit, c09 U_SubTypeA,
--        c10 updated, c11 on hand, c12 list-1 price ('' = no row), c13 currency, c14 the 64 property flags
--   C  customers                       c01 code, c02 name, c03 group name, c04 price list, c05 valid, c06 frozen
--   S  special prices (BP rows)        c01 item, c02 card, c03 price, c04 currency, c05 discount, c06 price list, c07 auto update, c08 valid
SELECT 'D' AS k, CAST(DB_NAME() AS nvarchar(254)) AS c01, CAST('' AS nvarchar(254)) AS c02, CAST('' AS nvarchar(254)) AS c03, CAST('' AS nvarchar(254)) AS c04,
	CAST('' AS nvarchar(254)) AS c05, CAST('' AS nvarchar(254)) AS c06, CAST('' AS nvarchar(254)) AS c07, CAST('' AS nvarchar(254)) AS c08, CAST('' AS nvarchar(254)) AS c09,
	CAST('' AS nvarchar(254)) AS c10, CAST('' AS nvarchar(254)) AS c11, CAST('' AS nvarchar(254)) AS c12, CAST('' AS nvarchar(254)) AS c13, CAST('' AS nvarchar(254)) AS c14
UNION ALL SELECT 'L', CAST(ListNum AS nvarchar(20)), ISNULL(ListName, ''), '', '', '', '', '', '', '', '', '', '', '', '' FROM OPLN WHERE ListNum = 1
UNION ALL SELECT 'P', CAST(ItmsTypCod AS nvarchar(20)), ISNULL(ItmsGrpNam, ''), '', '', '', '', '', '', '', '', '', '', '', '' FROM OITG
UNION ALL SELECT 'I', I.ItemCode, ISNULL(I.ItemName, ''), CAST(I.ItmsGrpCod AS nvarchar(20)), ISNULL(B.ItmsGrpNam, ''), ISNULL(I.SellItem, ''), ISNULL(I.frozenFor, ''),
	ISNULL(I.InvntryUom, ''), ISNULL(I.SalUnitMsr, ''), ISNULL(I.U_SubTypeA, ''), ISNULL(CONVERT(char(10), I.UpdateDate, 23), ''),
	CAST(CAST(ISNULL(I.OnHand, 0) AS decimal(19, 6)) AS nvarchar(40)), ISNULL(CAST(CAST(R.Price AS decimal(19, 6)) AS nvarchar(40)), ''), ISNULL(R.Currency, ''),
	ISNULL(I.QryGroup1, 'N') + ISNULL(I.QryGroup2, 'N') + ISNULL(I.QryGroup3, 'N') + ISNULL(I.QryGroup4, 'N') + ISNULL(I.QryGroup5, 'N') + ISNULL(I.QryGroup6, 'N') + ISNULL(I.QryGroup7, 'N') + ISNULL(I.QryGroup8, 'N') + ISNULL(I.QryGroup9, 'N') + ISNULL(I.QryGroup10, 'N') + ISNULL(I.QryGroup11, 'N') + ISNULL(I.QryGroup12, 'N') + ISNULL(I.QryGroup13, 'N') + ISNULL(I.QryGroup14, 'N') + ISNULL(I.QryGroup15, 'N') + ISNULL(I.QryGroup16, 'N') + ISNULL(I.QryGroup17, 'N') + ISNULL(I.QryGroup18, 'N') + ISNULL(I.QryGroup19, 'N') + ISNULL(I.QryGroup20, 'N') + ISNULL(I.QryGroup21, 'N') + ISNULL(I.QryGroup22, 'N') + ISNULL(I.QryGroup23, 'N') + ISNULL(I.QryGroup24, 'N') + ISNULL(I.QryGroup25, 'N') + ISNULL(I.QryGroup26, 'N') + ISNULL(I.QryGroup27, 'N') + ISNULL(I.QryGroup28, 'N') + ISNULL(I.QryGroup29, 'N') + ISNULL(I.QryGroup30, 'N') + ISNULL(I.QryGroup31, 'N') + ISNULL(I.QryGroup32, 'N') + ISNULL(I.QryGroup33, 'N') + ISNULL(I.QryGroup34, 'N') + ISNULL(I.QryGroup35, 'N') + ISNULL(I.QryGroup36, 'N') + ISNULL(I.QryGroup37, 'N') + ISNULL(I.QryGroup38, 'N') + ISNULL(I.QryGroup39, 'N') + ISNULL(I.QryGroup40, 'N') + ISNULL(I.QryGroup41, 'N') + ISNULL(I.QryGroup42, 'N') + ISNULL(I.QryGroup43, 'N') + ISNULL(I.QryGroup44, 'N') + ISNULL(I.QryGroup45, 'N') + ISNULL(I.QryGroup46, 'N') + ISNULL(I.QryGroup47, 'N') + ISNULL(I.QryGroup48, 'N') + ISNULL(I.QryGroup49, 'N') + ISNULL(I.QryGroup50, 'N') + ISNULL(I.QryGroup51, 'N') + ISNULL(I.QryGroup52, 'N') + ISNULL(I.QryGroup53, 'N') + ISNULL(I.QryGroup54, 'N') + ISNULL(I.QryGroup55, 'N') + ISNULL(I.QryGroup56, 'N') + ISNULL(I.QryGroup57, 'N') + ISNULL(I.QryGroup58, 'N') + ISNULL(I.QryGroup59, 'N') + ISNULL(I.QryGroup60, 'N') + ISNULL(I.QryGroup61, 'N') + ISNULL(I.QryGroup62, 'N') + ISNULL(I.QryGroup63, 'N') + ISNULL(I.QryGroup64, 'N')
	FROM OITM I LEFT JOIN OITB B ON B.ItmsGrpCod = I.ItmsGrpCod LEFT JOIN ITM1 R ON R.ItemCode = I.ItemCode AND R.PriceList = 1
	WHERE I.validFor = 'Y' AND (I.QryGroup1 = 'Y' OR I.QryGroup2 = 'Y' OR I.QryGroup3 = 'Y' OR I.QryGroup4 = 'Y' OR I.QryGroup5 = 'Y' OR I.QryGroup6 = 'Y' OR I.QryGroup7 = 'Y' OR I.QryGroup8 = 'Y' OR I.QryGroup9 = 'Y' OR I.QryGroup10 = 'Y' OR I.QryGroup11 = 'Y' OR I.QryGroup12 = 'Y' OR I.QryGroup13 = 'Y' OR I.QryGroup14 = 'Y' OR I.QryGroup15 = 'Y' OR I.QryGroup16 = 'Y' OR I.QryGroup17 = 'Y' OR I.QryGroup18 = 'Y' OR I.QryGroup19 = 'Y' OR I.QryGroup20 = 'Y' OR I.QryGroup21 = 'Y' OR I.QryGroup22 = 'Y' OR I.QryGroup23 = 'Y' OR I.QryGroup24 = 'Y' OR I.QryGroup25 = 'Y' OR I.QryGroup26 = 'Y' OR I.QryGroup27 = 'Y' OR I.QryGroup28 = 'Y' OR I.QryGroup29 = 'Y' OR I.QryGroup30 = 'Y' OR I.QryGroup31 = 'Y' OR I.QryGroup32 = 'Y' OR I.QryGroup33 = 'Y' OR I.QryGroup34 = 'Y' OR I.QryGroup35 = 'Y' OR I.QryGroup36 = 'Y' OR I.QryGroup37 = 'Y' OR I.QryGroup38 = 'Y' OR I.QryGroup39 = 'Y' OR I.QryGroup40 = 'Y' OR I.QryGroup41 = 'Y' OR I.QryGroup42 = 'Y' OR I.QryGroup43 = 'Y' OR I.QryGroup44 = 'Y' OR I.QryGroup45 = 'Y' OR I.QryGroup46 = 'Y' OR I.QryGroup47 = 'Y' OR I.QryGroup48 = 'Y' OR I.QryGroup49 = 'Y' OR I.QryGroup50 = 'Y' OR I.QryGroup51 = 'Y' OR I.QryGroup52 = 'Y' OR I.QryGroup53 = 'Y' OR I.QryGroup54 = 'Y' OR I.QryGroup55 = 'Y' OR I.QryGroup56 = 'Y' OR I.QryGroup57 = 'Y' OR I.QryGroup58 = 'Y' OR I.QryGroup59 = 'Y' OR I.QryGroup60 = 'Y' OR I.QryGroup61 = 'Y' OR I.QryGroup62 = 'Y' OR I.QryGroup63 = 'Y' OR I.QryGroup64 = 'Y')
UNION ALL SELECT 'C', C.CardCode, ISNULL(C.CardName, ''), ISNULL(G.GroupName, ''), CAST(ISNULL(C.ListNum, 0) AS nvarchar(20)), ISNULL(C.validFor, ''), ISNULL(C.frozenFor, ''), '', '', '', '', '', '', '', ''
	FROM OCRD C LEFT JOIN OCRG G ON G.GroupCode = C.GroupCode WHERE C.CardType = 'C'
UNION ALL SELECT 'S', S.ItemCode, S.CardCode, CAST(CAST(ISNULL(S.Price, 0) AS decimal(19, 6)) AS nvarchar(40)), ISNULL(S.Currency, ''),
	CAST(CAST(ISNULL(S.Discount, 0) AS decimal(19, 6)) AS nvarchar(40)), CAST(ISNULL(S.ListNum, 0) AS nvarchar(20)), ISNULL(S.AutoUpdt, ''), ISNULL(S.Valid, ''), '', '', '', '', '', ''
	FROM OSPP S WHERE S.CardCode NOT LIKE '*%'
